# Shared helpers for the RAP benchmark harness (issue #1687).
# Sourced by the other scripts; not executable on its own.
# All talk to one instance, selected by PORT (8191 = off, 8192 = on).

BENCH_ROOT="${BENCH_ROOT:-/tmp/rap1687-bench}"
# Database passwords are generated by setup.sh under BENCH_ROOT, not stored in the repo.
[ -f "$BENCH_ROOT/db.env" ] && . "$BENCH_ROOT/db.env"
API() { echo "http://localhost:$1/api/v1"; }

# Cookie jar per instance; the PHP session id doubles as the SESSION atom id.
jar() { echo "$BENCH_ROOT/session-$1.cookies"; }
sid() { awk '$6=="PHPSESSID" {print $7}' "$(jar "$1")"; }

# One replay transaction; body on stdin; prints the JSON response.
replay() { # $1=port
  curl -s -b "$(jar "$1")" -X POST "$(API "$1")/admin/replay/txn" \
    -H "Content-Type: application/json" -d @-
}

# Establish a session, mimic a login at the data level (sessionAccount +
# active account properties; SIAM's ExecEngine grants the roles), and
# activate the User role. Idempotent.
login() { # $1=port
  local port="$1"
  curl -s -c "$(jar "$port")" "$(API "$port")/app/navbar" > /dev/null
  local s; s="$(sid "$port")"
  replay "$port" <<EOF > /dev/null
{"ops":[
 {"op":"add","relation":"accUserid[Account*Userid]","src":"acc-driver","tgt":"driver"},
 {"op":"add","relation":"accIsActive[Account*Account]","src":"acc-driver","tgt":"acc-driver"},
 {"op":"add","relation":"accIsInitialized[Account*Account]","src":"acc-driver","tgt":"acc-driver"},
 {"op":"add","relation":"accAllowedRoles[Account*Role]","src":"acc-driver","tgt":"Tutor"},
 {"op":"add","relation":"sessionAccount[SESSION*Account]","src":"$s","tgt":"acc-driver"}
]}
EOF
  activate_role "$port" User
}

activate_role() { # $1=port $2=role (the single active role; all others off)
  local port="$1" role="$2" body="["
  for r in Anonymous User Tutor; do
    [ "$r" = "$role" ] && body+="{\"id\":\"$r\",\"active\":true}," \
                       || body+="{\"id\":\"$r\",\"active\":false},"
  done
  curl -s -b "$(jar "$port")" -X PATCH "$(API "$port")/app/roles" \
    -H "Content-Type: application/json" -d "${body%,}]" > /dev/null
}

# Timed GET: prints "http_code<TAB>seconds".
timed_get() { # $1=port $2=path-under-/api/v1
  curl -s -o /dev/null -w "%{http_code}\t%{time_total}" \
    -b "$(jar "$1")" "$(API "$1")/$2"
}

db_port() { case "$1" in 8191) echo 3491;; 8192) echo 3492;; esac; }
db_name() { case "$1" in 8191) echo rap1687off;; 8192) echo rap1687on;; esac; }

sql() { # $1=port  $2=sql (runs as root against the instance's database)
  docker exec "rap1687bench-db-$( [ "$1" = 8191 ] && echo off || echo on )" \
    mariadb -uroot -p"$RAP_BENCH_ROOT_PW" "$(db_name "$1")" -N -B -e "$2"
}
